# Optimizing get_distance for slightly larger m
import networkx as nx
from itertools import permutations
from collections import deque

def get_distance_fast(m):
    perms = list(permutations(range(m)))
    # Precompute rotation orbits
    orbit_map = {}
    orbit_count = 0
    for p in perms:
        if p not in orbit_map:
            curr = p
            for _ in range(m):
                orbit_map[curr] = orbit_count
                curr = curr[1:] + (curr[0],)
            orbit_count += 1

    # Build orbit graph
    G_orbits = nx.Graph()
    G_orbits.add_nodes_from(range(orbit_count))
    for p in perms:
        u = orbit_map[p]
        for i in range(m):
            p_list = list(p)
            p_list[i], p_list[(i+1)%m] = p_list[(i+1)%m], p_list[i]
            v = orbit_map[tuple(p_list)]
            if u != v:
                G_orbits.add_edge(u, v)

    return nx.diameter(G_orbits)

print(f"m=8, diameter={get_distance_fast(8)}")

